export default function main(input) {
  // ISO-Datum aus der Line-Item-Property 'Wunschtermin' ziehen.
  // Das Theme speichert dort das deutsche Langdatum UND das Cart-Attribut
  // 'Buchungsdatum'; fuer den Zaehler brauchen wir YYYY-MM-DD — wir parsen
  // das deutsche Datum ('Samstag, 14. Juni 2026') nach ISO.
  const MONTHS = {Januar:1,Februar:2,März:3,April:4,Mai:5,Juni:6,Juli:7,August:8,September:9,Oktober:10,November:11,Dezember:12};
  const prop = (input.order.lineItems || [])
    .flatMap(li => li.customAttributes || [])
    .find(a => a.key === 'Wunschtermin');
  if (!prop) return { skip: true };
  const m = prop.value.match(/(\d{1,2})\. (\w+) (\d{4})/);
  if (!m) return { skip: true };
  const iso = `${m[3]}-${String(MONTHS[m[2]]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  const map = JSON.parse(input.currentMap || '{}');
  map[iso] = (map[iso] || 0) + 1;
  return { newMap: JSON.stringify(map), skip: false };
}
